CREATE TYPE "CampaignOpportunityStatus" AS ENUM ('CANDIDATE','INCLUDED','EXCLUDED','COMPLETED','CANCELLED');
CREATE TYPE "CampaignCostType" AS ENUM ('RESEARCH','OUTREACH','DATA','COMMUNICATION','DILIGENCE','LEGAL','OTHER');
ALTER TABLE "AcquisitionCampaignBoundary" ADD COLUMN "allowedCounties" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], ADD COLUMN "allowedCities" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], ADD COLUMN "allowedZipCodes" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], ADD COLUMN "allowedNeighborhoods" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], ADD COLUMN "radiusCenterLatitude" DOUBLE PRECISION, ADD COLUMN "radiusCenterLongitude" DOUBLE PRECISION, ADD COLUMN "radiusMiles" DOUBLE PRECISION, ADD COLUMN "mapPolygon" JSONB, ADD COLUMN "includedPropertyTypes" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], ADD COLUMN "excludedPropertyTypes" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], ADD COLUMN "acquisitionStrategy" TEXT, ADD COLUMN "developmentFilters" JSONB, ADD COLUMN "priceFilters" JSONB, ADD COLUMN "targetBuyerGroup" TEXT, ADD COLUMN "minimumRequiredProfitCents" BIGINT, ADD COLUMN "maximumEarnestMoneyCents" BIGINT, ADD COLUMN "maximumResearchCostCents" BIGINT, ADD COLUMN "maximumOutreachCostCents" BIGINT, ADD COLUMN "evidenceFreshnessHours" INTEGER;
ALTER TABLE "AcquisitionCampaignBoundary" ADD CONSTRAINT "AcquisitionCampaignBoundary_limits_check" CHECK (COALESCE("minimumRequiredProfitCents",0) >= 0 AND COALESCE("maximumEarnestMoneyCents",0) >= 0 AND COALESCE("maximumResearchCostCents",0) >= 0 AND COALESCE("maximumOutreachCostCents",0) >= 0 AND COALESCE("evidenceFreshnessHours",1) > 0 AND COALESCE("radiusMiles",0) >= 0);
CREATE TABLE "CampaignOpportunity" ("id" TEXT PRIMARY KEY,"campaignId" TEXT NOT NULL,"funnelId" TEXT NOT NULL,"status" "CampaignOpportunityStatus" NOT NULL DEFAULT 'CANDIDATE',"reason" TEXT NOT NULL,"assignedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMP(3),CONSTRAINT "CampaignOpportunity_campaignId_fkey" FOREIGN KEY ("campaignId") REFERENCES "AcquisitionCampaign"("id") ON DELETE RESTRICT,CONSTRAINT "CampaignOpportunity_funnelId_fkey" FOREIGN KEY ("funnelId") REFERENCES "AcquisitionFunnel"("id") ON DELETE RESTRICT); CREATE UNIQUE INDEX "CampaignOpportunity_campaignId_funnelId_key" ON "CampaignOpportunity"("campaignId","funnelId"); CREATE INDEX "CampaignOpportunity_campaignId_status_assignedAt_idx" ON "CampaignOpportunity"("campaignId","status","assignedAt");
CREATE TABLE "CampaignAgentAssignment" ("id" TEXT PRIMARY KEY,"campaignId" TEXT NOT NULL,"agentId" TEXT NOT NULL,"responsibility" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"assignedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"removedAt" TIMESTAMP(3),"assignedBy" TEXT NOT NULL,CONSTRAINT "CampaignAgentAssignment_campaignId_fkey" FOREIGN KEY ("campaignId") REFERENCES "AcquisitionCampaign"("id") ON DELETE RESTRICT,CONSTRAINT "CampaignAgentAssignment_agentId_fkey" FOREIGN KEY ("agentId") REFERENCES "Agent"("id") ON DELETE RESTRICT); CREATE UNIQUE INDEX "CampaignAgentAssignment_campaignId_agentId_key" ON "CampaignAgentAssignment"("campaignId","agentId"); CREATE INDEX "CampaignAgentAssignment_agentId_active_idx" ON "CampaignAgentAssignment"("agentId","active");
CREATE TABLE "CampaignCostEntry" ("id" TEXT PRIMARY KEY,"campaignId" TEXT NOT NULL,"funnelId" TEXT,"type" "CampaignCostType" NOT NULL,"amountCents" BIGINT NOT NULL,"incurredAt" TIMESTAMP(3) NOT NULL,"sourceUrl" TEXT NOT NULL,"artifactHash" TEXT,"description" TEXT NOT NULL,"recordedBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "CampaignCostEntry_campaignId_fkey" FOREIGN KEY ("campaignId") REFERENCES "AcquisitionCampaign"("id") ON DELETE RESTRICT,CONSTRAINT "CampaignCostEntry_amount_check" CHECK ("amountCents" >= 0)); CREATE INDEX "CampaignCostEntry_campaignId_type_incurredAt_idx" ON "CampaignCostEntry"("campaignId","type","incurredAt"); CREATE INDEX "CampaignCostEntry_funnelId_incurredAt_idx" ON "CampaignCostEntry"("funnelId","incurredAt");
CREATE TABLE "CampaignGoalVersion" ("id" TEXT PRIMARY KEY,"campaignId" TEXT NOT NULL,"version" INTEGER NOT NULL,"discoveredTarget" INTEGER,"researchedTarget" INTEGER,"sellerContactTarget" INTEGER,"offerTarget" INTEGER,"contractTarget" INTEGER,"closeTarget" INTEGER,"realizedProfitTargetCents" BIGINT,"effectiveAt" TIMESTAMP(3) NOT NULL,"expiresAt" TIMESTAMP(3),"createdBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "CampaignGoalVersion_campaignId_fkey" FOREIGN KEY ("campaignId") REFERENCES "AcquisitionCampaign"("id") ON DELETE RESTRICT,CONSTRAINT "CampaignGoalVersion_targets_check" CHECK (COALESCE("discoveredTarget",0) >= 0 AND COALESCE("researchedTarget",0) >= 0 AND COALESCE("sellerContactTarget",0) >= 0 AND COALESCE("offerTarget",0) >= 0 AND COALESCE("contractTarget",0) >= 0 AND COALESCE("closeTarget",0) >= 0 AND COALESCE("realizedProfitTargetCents",0) >= 0)); CREATE UNIQUE INDEX "CampaignGoalVersion_campaignId_version_key" ON "CampaignGoalVersion"("campaignId","version"); CREATE INDEX "CampaignGoalVersion_campaignId_effectiveAt_expiresAt_idx" ON "CampaignGoalVersion"("campaignId","effectiveAt","expiresAt");
